 void status(const std::wstring& s){if(status_)SetWindowTextW(status_,s.c_str());}
 HWND control(int tab,int id,const wchar_t* klass,const wchar_t* text,int x,int y,int w,int h,DWORD style=0){HWND c=CreateWindowExW(0,klass,text,WS_CHILD|WS_VISIBLE|style,x,y,w,h,window_,reinterpret_cast<HMENU>(INT_PTR(id)),GetModuleHandleW(nullptr),nullptr);if(c){if(id>0&&id<640)controls_[id]=c;if(tab>=0&&tab<TAB_COUNT)tabItems_[tab].push_back(c);SendMessageW(c,WM_SETFONT,reinterpret_cast<WPARAM>(font_),TRUE);}return c;}
