 std::wstring materialKey(size_t part)const{if(part<materials_.size()&&!materials_[part].key.empty())return materials_[part].key;if(!manualTexturePath_.empty())return pathKey(manualTexturePath_);return L"__manual__";}
 bool loadPartDiffuse(size_t part,lab::Image& out,bool preview=false){out={};if(part<materials_.size()&&materials_[part].hasDiffuse){std::wstring e;out=loadImage(materials_[part].diffuse.wstring(),e);if(!out.valid()){status(e);return false;}if(preview&&std::max(out.w,out.h)>PREVIEW_MAX)out=lab::ResizeImageMax(out,PREVIEW_MAX);return out.valid();}if(sources_.diffuse.valid()){out=sources_.diffuse;if(preview&&std::max(out.w,out.h)>PREVIEW_MAX)out=lab::ResizeImageMax(out,PREVIEW_MAX);return true;}return false;}
 bool ensurePaintLayers(size_t part,bool create,std::shared_ptr<lab::Image>& normal,std::shared_ptr<lab::Image>& gloss,std::shared_ptr<lab::Image>& height){
  const std::wstring key=materialKey(part);auto ni=paintedNormals_.find(key),gi=paintedGloss_.find(key),hi=paintedHeight_.find(key);if(ni!=paintedNormals_.end()&&gi!=paintedGloss_.end()&&hi!=paintedHeight_.end()){normal=ni->second;gloss=gi->second;height=hi->second;return true;}if(!create)return false;
  lab::Image baseNormal,baseGloss,baseHeight;
  if(part<materials_.size()&&materials_[part].hasDiffuse){
   if(brushDiffuseKey_!=key||!brushDiffuse_.valid()){std::wstring e;brushDiffuse_=loadImage(materials_[part].diffuse.wstring(),e);if(brushDiffuse_.valid()&&std::max(brushDiffuse_.w,brushDiffuse_.h)>BRUSH_MAX)brushDiffuse_=lab::ResizeImageMax(brushDiffuse_,BRUSH_MAX);brushDiffuseKey_=key;if(!brushDiffuse_.valid()){status(e);return false;}}
   if(materials_[part].hasBump){std::wstring e1,e2;auto b=loadImage(materials_[part].bump.wstring(),e1),bx=loadImage(materials_[part].bumpX.wstring(),e2);if(b.valid()&&bx.valid()){if(std::max(b.w,b.h)>BRUSH_MAX)b=lab::ResizeImageMax(b,BRUSH_MAX);if(std::max(bx.w,bx.h)>BRUSH_MAX)bx=lab::ResizeImageMax(bx,BRUSH_MAX);baseNormal=lab::UnpackNormalMap(b,bx);baseGloss=lab::UnpackGlossMap(b);baseHeight=lab::UnpackHeightMap(bx);}}
   if(!baseNormal.valid()){baseNormal.w=brushDiffuse_.w;baseNormal.h=brushDiffuse_.h;baseNormal.pixels.assign(size_t(baseNormal.w)*baseNormal.h,lab::Pixel{128,128,255,255});}
  }else if(sources_.diffuse.valid()){
   if(useImported_&&importedBump_.valid()&&importedBumpX_.valid()){baseNormal=lab::UnpackNormalMap(importedBump_,importedBumpX_);baseGloss=lab::UnpackGlossMap(importedBump_);baseHeight=lab::UnpackHeightMap(importedBumpX_);}else if(sources_.normal.valid())baseNormal=sources_.normal;
   if(!baseNormal.valid()){baseNormal.w=sources_.diffuse.w;baseNormal.h=sources_.diffuse.h;if(std::max(baseNormal.w,baseNormal.h)>BRUSH_MAX){const float k=float(BRUSH_MAX)/float(std::max(baseNormal.w,baseNormal.h));baseNormal.w=std::max(1u,uint32_t(std::lround(baseNormal.w*k)));baseNormal.h=std::max(1u,uint32_t(std::lround(baseNormal.h*k)));}baseNormal.pixels.assign(size_t(baseNormal.w)*baseNormal.h,lab::Pixel{128,128,255,255});}
   if(!baseGloss.valid()&&sources_.gloss.valid())baseGloss=lab::ResizeImageMax(sources_.gloss,std::max(baseNormal.w,baseNormal.h));
   if(!baseHeight.valid()&&sources_.height.valid())baseHeight=lab::ResizeImageMax(sources_.height,std::max(baseNormal.w,baseNormal.h));
  }
  if(!baseNormal.valid())return false;
  if(!baseGloss.valid()||baseGloss.w!=baseNormal.w||baseGloss.h!=baseNormal.h){baseGloss.w=baseNormal.w;baseGloss.h=baseNormal.h;const uint8_t g=uint8_t(std::clamp(settings_.gloss,0.f,1.f)*255.f+0.5f);baseGloss.pixels.assign(size_t(baseGloss.w)*baseGloss.h,lab::Pixel{g,g,g,255});}
  if(!baseHeight.valid()||baseHeight.w!=baseNormal.w||baseHeight.h!=baseNormal.h){baseHeight.w=baseNormal.w;baseHeight.h=baseNormal.h;const uint8_t h=128;baseHeight.pixels.assign(size_t(baseHeight.w)*baseHeight.h,lab::Pixel{h,h,h,255});}
  normal=std::make_shared<lab::Image>(std::move(baseNormal));gloss=std::make_shared<lab::Image>(std::move(baseGloss));height=std::make_shared<lab::Image>(std::move(baseHeight));paintedNormals_[key]=normal;paintedGloss_[key]=gloss;paintedHeight_[key]=height;return true;
 }
 bool buildPartSources(size_t part,lab::Sources& src,bool preview,std::shared_ptr<lab::Image>& paintNormal,std::shared_ptr<lab::Image>& paintGloss,std::shared_ptr<lab::Image>& paintHeight){src={};paintNormal={};paintGloss={};paintHeight={};if(!loadPartDiffuse(part,src.diffuse,preview))return false;ensurePaintLayers(part,false,paintNormal,paintGloss,paintHeight);if(!paintNormal&&sources_.normal.valid())src.normal=sources_.normal;if(!paintGloss&&sources_.gloss.valid())src.gloss=sources_.gloss;if(!paintHeight&&sources_.height.valid())src.height=sources_.height;return true;}
 lab::BumpPair generateForPart(size_t part){lab::Sources src;std::shared_ptr<lab::Image> pn,pg,ph;if(!buildPartSources(part,src,true,pn,pg,ph))return {};lab::Image heldN,heldG,heldH;if(pn){heldN=std::move(*pn);src.normal=std::move(heldN);}if(pg){heldG=std::move(*pg);src.gloss=std::move(heldG);}if(ph){heldH=std::move(*ph);src.height=std::move(heldH);}lab::Settings neutral=settings_;neutral.normalStrength=1.f;neutral.invertY=false;if(pg)neutral.gloss=1.f;lab::BumpPair b=lab::GenerateBump(src,neutral);if(pn)*pn=std::move(src.normal);if(pg)*pg=std::move(src.gloss);if(ph)*ph=std::move(src.height);return b;}
 void applyBumpToMaterial(size_t part,const lab::BumpPair& b){if(!b.bump.valid())return;const std::wstring key=materialKey(part);for(size_t i=0;i<render_.PartCount();++i)if(materialKey(i)==key)render_.SetPartBumpImages(i,b.bump,b.bumpX,true);}

 lab::BumpPair manualBump(){if(!sources_.diffuse.valid())return {};const std::wstring key=materialKey(0);auto ni=paintedNormals_.find(key),gi=paintedGloss_.find(key),hi=paintedHeight_.find(key);if(ni!=paintedNormals_.end()&&gi!=paintedGloss_.end()&&hi!=paintedHeight_.end()&&ni->second&&gi->second&&hi->second){lab::Image oldN=std::move(sources_.normal),oldG=std::move(sources_.gloss),oldH=std::move(sources_.height);sources_.normal=std::move(*ni->second);sources_.gloss=std::move(*gi->second);sources_.height=std::move(*hi->second);lab::Settings neutral=settings_;neutral.normalStrength=1.f;neutral.invertY=false;neutral.gloss=1.f;lab::BumpPair b=lab::GenerateBump(sources_,neutral);*ni->second=std::move(sources_.normal);*gi->second=std::move(sources_.gloss);*hi->second=std::move(sources_.height);sources_.normal=std::move(oldN);sources_.gloss=std::move(oldG);sources_.height=std::move(oldH);return b;}if(useImported_&&importedBump_.valid()&&importedBumpX_.valid())return {importedBump_,importedBumpX_};lab::Settings neutral=settings_;neutral.normalStrength=1.f;neutral.invertY=false;return lab::GenerateBump(sources_,neutral);}
 void updateManualPreview(bool replaceDiffuse=false){if(!ready_)return;lab::BumpPair b=manualBump();if(!b.bump.valid()){status(L"Diffuse отсутствует");return;}if(replaceDiffuse)render_.SetImages(lab::ResizeImageMax(sources_.diffuse,PREVIEW_MAX),b.bump,b.bumpX);else render_.SetBumpImages(b.bump,b.bumpX,true);render_.SetNormalSettings(settings_.normalStrength,settings_.invertY);render_.SetGlossStrength(std::max(settings_.gloss,0.9f));generatedBumpMode_=!useImported_;autoModelMaterials_=false;InvalidateRect(preview_,nullptr,FALSE);}
 void loadSlot(int id){auto filename=pick(window_,L"Image (*.dds;*.png;*.jpg;*.bmp;*.tif)\0*.dds;*.png;*.jpg;*.jpeg;*.bmp;*.tif;*.tiff\0All files\0*.*\0",L"dds");if(filename.empty())return;std::wstring error;auto im=loadImage(filename,error);if(!im.valid()){MessageBoxW(window_,error.c_str(),L"Image",MB_ICONERROR);return;}if(id==LOAD_DIFF){sources_.diffuse=std::move(im);manualTexturePath_=filename;}else if(id==LOAD_NORMAL)sources_.normal=std::move(im);else if(id==LOAD_GLOSS)sources_.gloss=std::move(im);else if(id==LOAD_HEIGHT)sources_.height=std::move(im);else if(id==LOAD_BUMP)importedBump_=std::move(im);else if(id==LOAD_BUMPX)importedBumpX_=std::move(im);if(id==LOAD_BUMP||id==LOAD_BUMPX){useImported_=importedBump_.valid()&&importedBumpX_.valid();if(useImported_)generatedBumpMode_=false;if(!useImported_){status(L"Нужна пара bump/bump#");return;}updateManualPreview(false);}else{useImported_=false;if(sources_.diffuse.valid())updateManualPreview(id==LOAD_DIFF);}status(std::filesystem::path(filename).filename().wstring());}

 bool tryLoadOMF(const std::filesystem::path& file,lab::Mesh& mesh,std::wstring& loaded){std::error_code ec;if(!std::filesystem::is_regular_file(file,ec))return false;auto bytes=readFile(file.wstring());if(bytes.empty())return false;std::string reason;if(!lab::LoadOGFMotions(bytes,mesh,reason))return false;loaded=file.wstring();return true;}
 void loadExternalMotions(const std::filesystem::path& ogf,lab::Mesh& mesh,std::wstring& loaded){if(!mesh.motions.empty())return;std::vector<std::filesystem::path> refs;for(const auto& r:mesh.motionRefs){std::wstring w=widenPath(r);std::replace(w.begin(),w.end(),L'/',L'\\');std::filesystem::path p(w);if(p.extension().empty())p+=L".omf";refs.push_back(p);}if(refs.empty())refs.push_back(std::filesystem::path(ogf.stem().wstring()+L".omf"));const auto here=ogf.parent_path(),up=here.parent_path();for(const auto& ref:refs){std::vector<std::filesystem::path> candidates={here/ref,here/ref.filename(),up/ref,up/ref.filename()};for(const auto& c:candidates)if(tryLoadOMF(c,mesh,loaded))return;}}
