  brushHaveLast_=true;brushLastPart_=hit.part;brushLastU_=hit.u;brushLastV_=hit.v;ULONGLONG now=GetTickCount64();if(forcePreview||now-lastBrushPreview_>=70){lastBrushPreview_=now;updateBrushPreview(part);}std::wstring mode=L"Рельеф";if(brushTarget_==BrushTarget::Gloss)mode=L"Блеск "+std::to_wstring(int(std::lround(brushGloss_*100.f)))+L"%";else if(brushTarget_==BrushTarget::Height)mode=L"Высота "+std::to_wstring(int(std::lround(brushHeight_*100.f)))+L"%";status(L"UV "+std::to_wstring(hit.u)+L" / "+std::to_wstring(hit.v)+L" | "+mode);
