 void clearBrushLayer(){int p=render_.SelectedPart();if(p<0)return;const std::wstring key=materialKey(size_t(p));paintedNormals_.erase(key);paintedGloss_.erase(key);paintedHeight_.erase(key);brushUndo_.clear();currentUndo_={};currentUndoTiles_.clear();brushUndoBytes_=0;brushDiffuse_={};brushDiffuseKey_.clear();if(size_t(p)<materials_.size()&&materials_[size_t(p)].hasBump){std::wstring e1,e2;auto b=loadImage(materials_[size_t(p)].bump.wstring(),e1),bx=loadImage(materials_[size_t(p)].bumpX.wstring(),e2);if(b.valid()&&bx.valid()){b=lab::ResizeImageMax(b,PREVIEW_MAX);bx=lab::ResizeImageMax(bx,PREVIEW_MAX);for(size_t i=0;i<materials_.size();++i)if(materialKey(i)==key)render_.SetPartBumpImages(i,b,bx,true);}}else{generateBump(true);}InvalidateRect(preview_,nullptr,FALSE);status(L"Кисть очищена");}


 void click(int id){switch(id){case LOAD_DIFF:case LOAD_NORMAL:case LOAD_GLOSS:case LOAD_HEIGHT:case LOAD_BUMP:case LOAD_BUMPX:loadSlot(id);break;case LOAD_OGF:openOGF();break;case GENERATE:generateBump(false);break;case EXPORT:exportDDS();break;case RESET:resetScene();break;case CLEAR_SELECTION:clearSelection();break;case COLOR_TINT:chooseColor(0);break;case COLOR_LIGHT:chooseColor(1);break;case COLOR_AMBIENT:chooseColor(2);break;case INVERT_Y:settings_.invertY=SendMessageW(controls_[INVERT_Y],BM_GETCHECK,0,0)==BST_CHECKED;render_.SetNormalSettings(settings_.normalStrength,settings_.invertY);InvalidateRect(preview_,nullptr,FALSE);break;case BUMP_ENABLED:render_.BumpEnabled(SendMessageW(controls_[BUMP_ENABLED],BM_GETCHECK,0,0)==BST_CHECKED);InvalidateRect(preview_,nullptr,FALSE);break;case SKELETON_ENABLED:render_.SkeletonEnabled(SendMessageW(controls_[SKELETON_ENABLED],BM_GETCHECK,0,0)==BST_CHECKED);InvalidateRect(preview_,nullptr,FALSE);break;case SELECT_MODE:selectionMode_=SendMessageW(controls_[SELECT_MODE],BM_GETCHECK,0,0)==BST_CHECKED;if(selectionMode_){brushMode_=false;SendMessageW(controls_[BRUSH_MODE],BM_SETCHECK,BST_UNCHECKED,0);render_.ClearBrushCursor();}status(selectionMode_?L"Выделение":L"Камера");break;case ANIM_PLAY:toggleAnimation();break;case MESH_SHOW_ALL:showAllMeshes();break;case MESH_HIDE_SELECTED:hideSelectedMesh();break;case BRUSH_MODE:brushMode_=SendMessageW(controls_[BRUSH_MODE],BM_GETCHECK,0,0)==BST_CHECKED;if(brushMode_){selectionMode_=false;SendMessageW(controls_[SELECT_MODE],BM_SETCHECK,BST_UNCHECKED,0);}else render_.ClearBrushCursor();status(brushMode_?L"Кисть":L"Камера");InvalidateRect(preview_,nullptr,FALSE);break;case BRUSH_TARGET_RELIEF:brushTarget_=BrushTarget::Relief;SendMessageW(controls_[BRUSH_TARGET_RELIEF],BM_SETCHECK,BST_CHECKED,0);SendMessageW(controls_[BRUSH_TARGET_GLOSS],BM_SETCHECK,BST_UNCHECKED,0);SendMessageW(controls_[BRUSH_TARGET_HEIGHT],BM_SETCHECK,BST_UNCHECKED,0);status(L"Кисть: рельеф");break;case BRUSH_TARGET_GLOSS:brushTarget_=BrushTarget::Gloss;SendMessageW(controls_[BRUSH_TARGET_RELIEF],BM_SETCHECK,BST_UNCHECKED,0);SendMessageW(controls_[BRUSH_TARGET_GLOSS],BM_SETCHECK,BST_CHECKED,0);SendMessageW(controls_[BRUSH_TARGET_HEIGHT],BM_SETCHECK,BST_UNCHECKED,0);status(L"Кисть: блеск");break;case BRUSH_TARGET_HEIGHT:brushTarget_=BrushTarget::Height;SendMessageW(controls_[BRUSH_TARGET_RELIEF],BM_SETCHECK,BST_UNCHECKED,0);SendMessageW(controls_[BRUSH_TARGET_GLOSS],BM_SETCHECK,BST_UNCHECKED,0);SendMessageW(controls_[BRUSH_TARGET_HEIGHT],BM_SETCHECK,BST_CHECKED,0);status(L"Кисть: высота");break;case PRESET_LOAD:loadBrushPreset();break;case PRESET_SAVE:saveBrushPreset();break;case BRUSH_CLEAR:clearBrushLayer();break;}}
 void movedSlider(int id){if(id==SLIDER_NORMAL){settings_.normalStrength=SendMessageW(controls_[id],TBM_GETPOS,0,0)/100.f;render_.SetNormalSettings(settings_.normalStrength,settings_.invertY);InvalidateRect(preview_,nullptr,FALSE);}else if(id==SLIDER_GLOSS){settings_.gloss=SendMessageW(controls_[id],TBM_GETPOS,0,0)/200.f;if(generatedBumpMode_)generateBump(true);else{render_.SetGlossStrength(settings_.gloss);InvalidateRect(preview_,nullptr,FALSE);}}else if(id==SLIDER_HEIGHT){settings_.height=SendMessageW(controls_[id],TBM_GETPOS,0,0)/200.f;if(generatedBumpMode_)generateBump(true);}else if(id==SLIDER_BLUR){settings_.blur=SendMessageW(controls_[id],TBM_GETPOS,0,0)/100.f;if(generatedBumpMode_)generateBump(true);}else if(id==SLIDER_SHARP){settings_.sharpness=SendMessageW(controls_[id],TBM_GETPOS,0,0)/100.f;if(generatedBumpMode_)generateBump(true);}else if(id==SLIDER_LIGHT_AZ||id==SLIDER_LIGHT_EL){float az=float(SendMessageW(controls_[SLIDER_LIGHT_AZ],TBM_GETPOS,0,0));float el=float(SendMessageW(controls_[SLIDER_LIGHT_EL],TBM_GETPOS,0,0));render_.SetLightOrbitDegrees(az,el);saveLight();InvalidateRect(preview_,nullptr,FALSE);}else if(id==ANIM_TIMELINE){const auto* m=render_.MotionAt(animIndex_);if(m){stopAnimation();animTime_=float(SendMessageW(controls_[ANIM_TIMELINE],TBM_GETPOS,0,0))/m->fps;configureAnimation(animIndex_,false);}}else if(id==ANIM_SPEED){animSpeed_=SendMessageW(controls_[ANIM_SPEED],TBM_GETPOS,0,0)/100.f;}else if(id==BRUSH_RADIUS){const int value=int(SendMessageW(controls_[BRUSH_RADIUS],TBM_GETPOS,0,0));brushRadiusUv_=value/1000.f;wchar_t text[64];swprintf_s(text,L"Размер: %.1f%%",value/10.f);SetWindowTextW(controls_[BRUSH_RADIUS_TEXT],text);POINT p{};GetCursorPos(&p);ScreenToClient(preview_,&p);updateBrushCursor(p.x,p.y);InvalidateRect(preview_,nullptr,FALSE);}else if(id==BRUSH_GLOSS){brushGloss_=SendMessageW(controls_[BRUSH_GLOSS],TBM_GETPOS,0,0)/100.f;}else if(id==BRUSH_HEIGHT){brushHeight_=SendMessageW(controls_[BRUSH_HEIGHT],TBM_GETPOS,0,0)/100.f;}}

